class Solution:
    def minTaps(self, n, ranges):
        far = [0] * (n + 1)
        for i, r in enumerate(ranges):
            left, right = max(0, i - r), min(n, i + r)
            far[left] = max(far[left], right)
        ans = curr = nxt = 0
        for x in range(n):
            nxt = max(nxt, far[x])
            if x == curr:
                if nxt <= x:
                    return -1
                ans += 1
                curr = nxt
        return ans

